def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n >= 100:
        return 'D'
    me = [h[0] for h in history]
    opp = [h[1] for h in history]
    last_me = me[-1]
    last_opp = opp[-1]
    opp_c = opp.count('C')
    opp_d = n - opp_c

    # Detect strong patterns
    if n >= 6:
        last6 = opp[-6:]
        d6 = last6.count('D')
        if d6 >= 5:
            return 'D' if n % 5 != 0 else 'C'

    if n >= 10:
        recent_d = opp[-10:].count('D')
        if recent_d >= 8:
            return 'D'
        if recent_d == 0 and last_opp == 'C':
            # Opponent very nice. Exploit occasionally late-mid.
            if n >= 20 and n % 13 == 0:
                return 'D'
            return 'C'

    # Endgame: last few rounds vs a non-punishing opponent
    if n >= 95:
        if opp_d == 0:
            return 'D'
        if opp_d * 4 <= n:
            return 'C'
        return 'D'

    if n >= 90:
        if opp_d == 0:
            return 'D' if n % 2 == 0 else 'C'
        if opp_d * 3 <= n:
            return 'C'
        return 'D'

    # TFT-with-forgiveness core
    if last_opp == 'D':
        if last_me == 'D':
            # mutual defection - try to break spiral
            run = 0
            for i in range(n - 1, -1, -1):
                if me[i] == 'D' and opp[i] == 'D':
                    run += 1
                else:
                    break
            if run >= 3 and rng.random() < 0.3:
                return 'C'
            return 'D'
        else:
            # opponent defected while we cooperated
            if n >= 4 and opp[-4:].count('D') >= 3:
                return 'D'
            if opp_d >= 10 and opp_c >= 10 and opp_d * 2 >= n:
                return 'D'
            if rng.random() < 0.15:
                return 'C'
            return 'D'

    # last_opp == 'C'
    if last_me == 'D':
        return 'C'
    # both cooperated: check for long cooperative streak -> probe
    run_c = 0
    for a in reversed(opp):
        if a == 'C':
            run_c += 1
        else:
            break
    if run_c >= 5 and n >= 25:
        if rng.random() < 0.12:
            return 'D'
    return 'C'
